// AUTO-GENERATED by scripts/build-views.mjs — do not edit by hand.
// Stargaze apartments (floor*100 + svg-position) that have a courtyard
// panorama. Sold-out apartments are absent, so they're hidden from the
// floor dropdown in the courtyard view.
export const STARGAZE_VIEW_APTS = [201, 202, 301, 302, 303, 304, 402, 403, 503, 603, 604, 702, 703, 704, 805, 902, 903, 904, 1002, 1003, 1005, 1102, 1103, 1202, 1203, 1205, 1302, 1303, 1305, 1402, 1505, 1602, 1603, 1605, 1703, 1705, 1803, 1903, 2002, 2005, 2102, 2103, 2302, 2303, 2402, 2403, 2502, 2503, 2805, 3005, 3102, 3105, 3206, 3302, 3405, 3502, 3506, 3602, 3606, 3702, 3706]

const VIEW_SET = new Set(STARGAZE_VIEW_APTS)

// Apartment number for a floor (1-39) + svg position (1-6).
export const aptNumber = (floor, position) => floor * 100 + position

// Public path to a panorama, or null when that apartment is sold out.
export const viewImage = (floor, position) =>
  VIEW_SET.has(aptNumber(floor, position))
    ? `/unit/views/${aptNumber(floor, position)}.webp`
    : null

// Floors (ascending) where the given svg position has a panorama.
export const floorsForPosition = (position) =>
  STARGAZE_VIEW_APTS.filter((a) => a % 100 === position).map((a) =>
    Math.floor(a / 100),
  )
